function ml(k,v={}){let s=moduleText[k]?.[exIndex()]||k;for(const [key,value]of Object.entries(v))s=s.replaceAll('{'+key+'}',String(value));return s}
const SHAMS_FEATURES=Object.freeze({personalDuas:true,quiz:true,asma:true,premiumPayments:false,cloudSync:false,backgroundPush:false});
function safeWrite(k,v){try{save(k,v);return true}catch{toast(ml('storageError'));return false}}
function shuffleItems(list){const a=[...list];for(let i=a.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]]}return a}
function modWrap(html){return `<section class="module-view" data-localized="true">${html}</section>`}
function pageLinks(page,total,action){return `<div class="quran-pagination"><button class="secondarybtn" aria-label="${ml('previous')}" ${page===0?'disabled':''} onclick="${action}(${page-1})">←</button><span>${page+1} / ${Math.max(1,total)}</span><button class="secondarybtn" aria-label="${ml('next')}" ${page>=total-1?'disabled':''} onclick="${action}(${page+1})">→</button></div>`}
let contentReturnFocus=null;
function showContentModal(html){let e=document.querySelector('#contentModal');if(!e){contentReturnFocus=document.activeElement;e=document.createElement('section');e.id='contentModal';e.className='modal-layer';e.setAttribute('role','dialog');e.setAttribute('aria-modal','true');document.body.appendChild(e);document.querySelector('main').inert=true;document.querySelector('#bottomNav').inert=true}e.innerHTML=`<div class="content-sheet" data-localized="true">${html}</div>`;const heading=e.querySelector('h2');if(heading){heading.id='contentDialogTitle';e.setAttribute('aria-labelledby',heading.id)}e.querySelector('button')?.focus({preventScroll:true})}
function modalHeading(title){return `<div class="sheet-head"><h2>${esc(title)}</h2><button aria-label="${ml('close')}" onclick="closeContentModal()">×</button></div>`}
function closeContentModal(){document.querySelector('#contentModal')?.remove();document.querySelector('main').inert=false;document.querySelector('#bottomNav').inert=false;contentReturnFocus?.focus?.({preventScroll:true})}
const duaCategories=['morning','evening','health','family','provision','forgiveness','gratitude','travel','intention','other'];
let collectionQuery='',collectionTab='all',collectionCategory='',collectionPageIndex=0,collectionEditing=null;
function readDuaBook(){const s=read('shams-dua-book',{});return {version:1,revision:Number(s?.revision)||0,entries:Array.isArray(s?.entries)?s.entries.filter(e=>e&&/^[\w-]+$/.test(e.id)&&typeof e.title==='string'&&typeof e.body==='string'):[],library:s?.library&&typeof s.library==='object'?s.library:{},categories:Array.isArray(s?.categories)?s.categories.filter(x=>typeof x==='string').slice(0,100):[]}}
function bookEntries(){const b=readDuaBook();return [...allDuas().map(d=>({...b.library[d.id],id:'lib-'+d.id,kind:'library',title:d.title,body:d.arabic+'\n\n'+d.meaning,source:d.source,sourceUrl:d.sourceUrl,category:b.library[d.id]?.category||({0:'morning',1:'evening',2:'provision',3:'travel',4:'family'})[d.id]||'other'})),...b.entries.map(d=>({...d,kind:'personal'}))]}
function catLabel(c){return duaCategories.includes(c)?ml(c):c}
function filteredBookEntries(){const q=normalizeSearch(collectionQuery);return bookEntries().filter(d=>(collectionTab!=='favorites'||d.favorite)&&(collectionTab!=='daily'||d.daily||d.reminder?.repeat==='daily')&&(collectionTab!=='personal'||d.kind==='personal')&&(!collectionCategory||d.category===collectionCategory)&&normalizeSearch(d.title+' '+d.body+' '+catLabel(d.category)).includes(q))}
function bookCard(d){return `<article class="book-card"><div><button class="book-title" onclick="openBookDua('${d.id}')"><strong>${esc(d.title)}</strong><p>${esc(d.body.slice(0,130))}${d.body.length>130?'…':''}</p></button><button class="favorite-button" aria-label="${ml(d.favorite?'unfavorite':'favorite')} · ${esc(d.title)}" aria-pressed="${!!d.favorite}" onclick="toggleBookFavorite('${d.id}')">${d.favorite?'♥':'♡'}</button></div><footer><span>${esc(catLabel(d.category))}</span><span>${d.reminder?.repeat&&d.reminder.repeat!=='off'?'◷ '+esc(d.reminder.time)+' · '+ml(d.reminder.repeat):ml('off')}</span><button onclick="openBookDua('${d.id}')" aria-label="${ml('detail')} · ${esc(d.title)}">›</button></footer></article>`}
function collectionResults(){const b=readDuaBook();if(collectionTab==='categories'&&!collectionCategory)return `<div class="category-grid">${[...duaCategories,...b.categories].map(c=>`<button data-category="${esc(encodeURIComponent(c))}" onclick="chooseBookCategory(this.dataset.category)"><span>✧</span><strong>${esc(catLabel(c))}</strong><small>${bookEntries().filter(e=>e.category===c).length}</small></button>`).join('')}</div>`;const list=filteredBookEntries(),size=(window.innerHeight||740)>900?4:3,pages=Math.max(1,Math.ceil(list.length/size));collectionPageIndex=Math.max(0,Math.min(collectionPageIndex,pages-1));return list.length?list.slice(collectionPageIndex*size,(collectionPageIndex+1)*size).map(bookCard).join('')+pageLinks(collectionPageIndex,pages,'setBookPage'):`<div class="module-empty">♡<p>${ml('empty')}</p><button class="goldbtn" onclick="editBookDua()">+ ${ml('add')}</button></div>`}
function collectionPage(){return modWrap(head(ux('myDuas'),'')+`<div class="module-toolbar"><input type="search" aria-label="${ml('search')}" placeholder="${ml('search')}" value="${esc(collectionQuery)}" oninput="collectionQuery=this.value;collectionPageIndex=0;refreshBookResults()"><button class="goldbtn" onclick="editBookDua()" aria-label="${ml('add')}">＋</button></div><div class="chip-tabs" data-swipe-lock="true">${['all','favorites','daily','personal','categories'].map(t=>`<button aria-pressed="${collectionTab===t}" onclick="setBookTab('${t}')">${ml(t)}</button>`).join('')}</div>${collectionCategory?`<button class="textbtn" onclick="chooseBookCategory('')">← ${esc(catLabel(collectionCategory))}</button>`:''}<div id="bookResults">${collectionResults()}</div><details class="module-help"><summary>${ml('privacy')}</summary><p>${ml('reminderLimit')}</p><button class="secondarybtn" onclick="requestNotices()">${ml('allow')}</button></details>`)}
function refreshBookResults(){const e=document.querySelector('#bookResults');if(e)e.innerHTML=collectionResults()}
function setBookTab(t){collectionTab=t;collectionCategory='';collectionPageIndex=0;render()}
function chooseBookCategory(c){collectionCategory=decodeURIComponent(c);collectionTab='categories';collectionPageIndex=0;render()}
function setBookPage(n){collectionPageIndex=n;refreshBookResults();document.querySelector('#bookResults')?.scrollIntoView({block:'start'})}
function updateBookEntry(id,mutate){const b=readDuaBook();if(id.startsWith('lib-')){const n=id.slice(4);b.library[n]=mutate(b.library[n]||{})}else{const at=b.entries.findIndex(e=>e.id===id);if(at<0)return false;b.entries[at]=mutate(b.entries[at])}b.revision++;return safeWrite('shams-dua-book',b)}
function toggleBookFavorite(id){if(updateBookEntry(id,d=>({...d,favorite:!d.favorite,updatedAt:Date.now()})))refreshBookResults()}
function openBookDua(id){const d=bookEntries().find(e=>e.id===id);if(!d)return;showContentModal(modalHeading(d.title)+`<div class="book-full" dir="auto">${esc(d.body)}</div>${d.note?`<section class="meaning"><strong>${ml('note')}</strong><p>${esc(d.note)}</p></section>`:''}<p class="notice">${esc(catLabel(d.category))} · ${d.reminder?.repeat&&d.reminder.repeat!=='off'?esc(d.reminder.time)+' · '+ml(d.reminder.repeat):ml('off')}</p><div class="module-actions"><button class="goldbtn" onclick="editBookDua('${id}')">${ml('edit')}</button>${d.kind==='personal'?`<button class="secondarybtn danger" onclick="confirmBookDelete('${id}')">${ml('remove')}</button>`:''}</div>`)}
function editBookDua(id=''){const d=bookEntries().find(e=>e.id===id),b=readDuaBook();collectionEditing={id,updatedAt:d?.updatedAt||0};const custom=d?.kind!=='library',rem=d?.reminder||{repeat:'off',time:'08:00',weekday:1};showContentModal(modalHeading(d?ml('edit'):ml('add'))+`<form id="duaEditor" onsubmit="event.preventDefault();saveBookForm(this)">${custom?`<label class="field-label">${ml('title')}<input name="title" required maxlength="100" value="${esc(d?.title||'')}"></label><label class="field-label">${ml('body')}<textarea name="body" required rows="5" maxlength="12000" dir="auto">${esc(d?.body||'')}</textarea></label>`:`<p class="notice">${esc(d.title)}</p>`}<label class="field-label">${ml('category')}<select name="category" onchange="this.form.querySelector('[name=newCategory]').hidden=this.value!=='__new'">${[...duaCategories,...b.categories].map(c=>`<option value="${esc(c)}" ${d?.category===c?'selected':''}>${esc(catLabel(c))}</option>`).join('')}<option value="__new">${ml('newCategory')}</option></select><input name="newCategory" maxlength="60" placeholder="${ml('categoryName')}" aria-label="${ml('categoryName')}" hidden></label><label class="field-label">${ml('note')}<textarea name="note" rows="2" maxlength="1000">${esc(d?.note||'')}</textarea></label><div class="form-columns"><label class="field-label">${ml('time')}<input type="time" name="time" value="${esc(rem.time||'08:00')}" required></label><label class="field-label">${ml('reminder')}<select name="repeat" onchange="this.form.querySelector('[data-weekday]').hidden=this.value!=='weekly'">${['off','daily','weekly'].map(r=>`<option value="${r}" ${r===rem.repeat?'selected':''}>${ml(r)}</option>`).join('')}</select></label></div><label data-weekday class="field-label" ${rem.repeat==='weekly'?'':'hidden'}>${ml('weekday')}<select name="weekday">${Array.from({length:7},(_,i)=>`<option value="${i}" ${Number(rem.weekday)===i?'selected':''}>${weekdayLabel(i)}</option>`).join('')}</select></label><label class="form-check"><input type="checkbox" name="favorite" ${d?.favorite?'checked':''}>${ml('favorite')}</label><label class="form-check"><input type="checkbox" name="daily" ${d?.daily?'checked':''}>${ml('daily')}</label><p class="notice">${ml('privacy')}</p><p class="notice">${ml('reminderLimit')}</p><button type="button" class="textbtn" onclick="requestNotices()">${ml('allow')}</button><p id="bookFormError" class="error" role="status"></p><button class="goldbtn" type="submit">${ml('save')}</button></form>`)}
function saveBookForm(form){const f=new FormData(form),b=readDuaBook(),old=bookEntries().find(e=>e.id===collectionEditing.id);if(old&&(old.updatedAt||0)!==collectionEditing.updatedAt){document.querySelector('#bookFormError').textContent=ml('conflict');return}const title=String(f.get('title')||'').trim().slice(0,100),body=String(f.get('body')||'').trim().slice(0,12000);if(old?.kind!=='library'&&(!title||!body)){document.querySelector('#bookFormError').textContent=ml('required');return}let category=String(f.get('category')||'other');if(category==='__new'){category=String(f.get('newCategory')||'').trim().slice(0,60);if(!category){document.querySelector('#bookFormError').textContent=ml('categoryName');return}if(!duaCategories.includes(category)&&!b.categories.includes(category))b.categories.push(category)}const repeat=['off','daily','weekly'].includes(f.get('repeat'))?f.get('repeat'):'off',time=String(f.get('time')||'08:00');if(!/^\d{2}:\d{2}$/.test(time))return;const fields={category,note:String(f.get('note')||'').trim().slice(0,1000),favorite:f.get('favorite')==='on',daily:f.get('daily')==='on',reminder:{repeat,time,weekday:Math.max(0,Math.min(6,Number(f.get('weekday'))||0))},updatedAt:Date.now()};if(old?.kind==='library')b.library[old.id.slice(4)]={...b.library[old.id.slice(4)],...fields};else if(old){const i=b.entries.findIndex(e=>e.id===old.id);b.entries[i]={...old,...fields,title,body}}else b.entries.push({...fields,id:'dua-'+Date.now().toString(36)+'-'+Math.random().toString(36).slice(2,8),title,body});b.revision++;if(safeWrite('shams-dua-book',b)){closeContentModal();render();checkPersonalReminders()}}
function confirmBookDelete(id){const d=bookEntries().find(x=>x.id===id&&x.kind==='personal');if(!d)return;showContentModal(modalHeading(ml('deleteQuestion'))+`<p>${esc(d.title)}</p><p class="notice">${ml('deleteInfo')}</p><div class="module-actions"><button class="secondarybtn" onclick="openBookDua('${id}')">${ml('cancel')}</button><button class="goldbtn danger" onclick="deleteBookDua('${id}')">${ml('confirmDelete')}</button></div>`)}
function deleteBookDua(id){const b=readDuaBook();b.entries=b.entries.filter(e=>e.id!==id);b.revision++;if(safeWrite('shams-dua-book',b)){closeContentModal();render()}}
function dueDuaReminder(rem,now){if(!rem||!['daily','weekly'].includes(rem.repeat))return false;return rem.time===String(now.getHours()).padStart(2,'0')+':'+String(now.getMinutes()).padStart(2,'0')&&(rem.repeat==='daily'||Number(rem.weekday)===now.getDay())}
function checkPersonalReminders(){const now=new Date(),date=key(now),sent=read('shams-dua-reminders',{});for(const d of bookEntries()){if(!dueDuaReminder(d.reminder,now))continue;const k=date+'|'+d.id+'|'+d.reminder.time;if(sent[k])continue;toast(ml('reminderBody'));if(typeof Notification!=='undefined'&&Notification.permission==='granted')try{new Notification('Shams',{body:ml('reminderBody')})}catch{}sent[k]=true}const keys=Object.keys(sent).sort().slice(-600),small=Object.fromEntries(keys.map(k=>[k,sent[k]]));safeWrite('shams-dua-reminders',small)}
function initializeCompanion(){window.addEventListener('hashchange',()=>{if(fastDraft)closeFastModal();if(document.querySelector('#contentModal'))closeContentModal()});setInterval(checkPersonalReminders,30000);window.addEventListener('storage',e=>{if(['shams-dua-book','shams-quiz','shams-names'].includes(e.key)&&!document.querySelector('#contentModal')&&['collection','quiz','asma'].includes(route))render()});document.addEventListener('keydown',e=>{const modal=document.querySelector('#contentModal');if(!modal)return;if(e.key==='Escape'){closeContentModal();return}if(e.key==='Tab'){const list=[...modal.querySelectorAll('button:not(:disabled),input:not([hidden]),textarea,select,a[href]')].filter(e=>e.offsetParent!==null),a=list[0],z=list.at(-1);if(e.shiftKey&&document.activeElement===a){e.preventDefault();z?.focus()}else if(!e.shiftKey&&document.activeElement===z){e.preventDefault();a?.focus()}}});}
